```cpp
const KArchiveEntry *KArchiveDirectory::entry(const QString &_name) const
{
    QString name = QDir::cleanPath(_name);
    int pos = name.indexOf('/');
    if (pos == 0) {
        if (name.length() > 1) {
            name = name.mid(1);
            pos = name.indexOf('/');
        } else {
            return this;
        }
    }
    if (pos != -1 && pos == name.length() - 1) {
        name = name.left(pos);
        pos = name.indexOf('/');
    }
    if (pos != -1) {
        const QString left = name.left(pos);
        const QString right = name.mid(pos + 1);
        const KArchiveEntry *e = d->entries.value(left);
        if (!e || !e->isDirectory()) {
            return nullptr;
        }
        return static_cast<const KArchiveDirectory *>(e)->entry(right);
    }
    return d->entries.value(name);
}
```

So `entry()` traverses the directory tree. If at any point an entry is not a directory, it returns nullptr.

Now, the key insight: in `findOrCreate`, when we find a zero-size file and delete it, we then recursively call `findOrCreate` for the parent. But what if the parent was already found earlier in the same `findOrCreate` call?

